/// <summary>
/// COC extension class of  <c>PurchLineSalesPurchLine</c> class in Metcash.
/// </summary>
[ExtensionOf(classStr(PurchLineSalesPurchLine))]
internal final class METPurchLineSalesPurchLine_Extension
{
}

Method.Source:
/// <summary>
/// Sets prices and discounts on the <c>PurchLine</c>.
/// </summary>
/// <param name = "_inventDim">An <c>InventDim</c> record.</param>
/// <param name = "_initDateFields">A <c>boolean</c> value.</param>
/// <param name = "_parameters">An instance of the <c>PriceDiscPriceAgreementParameters</c> class, used to pass any additional parameters.</param>
public void setPriceDisc(InventDim _inventDim, boolean _initDateFields, PriceDiscPriceAgreementParameters _parameters)
{
    next setPriceDisc(_inventDim, _initDateFields, _parameters);

    //passing CheckPolicy as null, since setPriceAgrrement initializes checkPolicy if found null in the same way before calling setPriceAgreement in setPriceDisc method.
    if (!this.mustSetPriceAgreement(_inventDim, null, _parameters))
    {
        return;
    }

    if (FeatureStateProvider::IsFeatureEnabled(KittingFeature::instance()))
    {
        if (this.kittingSkipSetPriceAgreement(false))
        {
            return;
        }
    }

    if (this.mustSetPriceDisc(_inventDim, _initDateFields, _parameters))
    {
        PurchTable purchTable = this.salesPurchTable() as PurchTable;

        if (purchTable.RecId && (purchTable.METIntercompanyTransferReplenishment 
            || purchTable.InterCompanyOrigin == InterCompanyOrigin::Derived))
        {
            PriceCur priceCur;
            LineAmount lineAmount;
            PurchLine purchLine = this.parmSalesPurchLine() as PurchLine;
            [priceCur, lineAmount]= purchLine.metOverwriteSetPriceDisc(this.parmSalesPurchLine());
            this.assignPrice(priceCur);
            this.assignLineAmount(lineAmount);
        }
    }
}
